import React, { createContext, useCallback, useContext, useMemo, useState } from 'react';
import {
  initialCouriers,
  initialCustomers,
  initialOrders,
  initialPayments,
  initialProducts,
  initialPromotions,
  initialStaff,
  categories as seedCategories,
  type Category,
  type Courier,
  type Customer,
  type Order,
  type OrderStatus,
  type Payment,
  type Product,
  type Promotion,
  type StaffMember,
} from './mock';

export interface StoreSettings {
  storeName: string;
  phone: string;
  email: string;
  address: string;
  currency: string;
  language: string;
  freeDeliveryThreshold: number;
  deliveryFee: number;
  minOrderAmount: number;
  workingHours: string;
  theme: 'light' | 'dark' | 'system';
  orderNotifications: boolean;
  promoNotifications: boolean;
}

interface Toast {
  id: number;
  message: string;
  type: 'success' | 'error' | 'info';
}

interface AdminContextValue {
  products: Product[];
  categories: Category[];
  orders: Order[];
  couriers: Courier[];
  customers: Customer[];
  promotions: Promotion[];
  payments: Payment[];
  staff: StaffMember[];
  settings: StoreSettings;
  toasts: Toast[];
  notify: (message: string, type?: Toast['type']) => void;
  dismissToast: (id: number) => void;
  saveProduct: (product: Product) => void;
  deleteProduct: (id: string) => void;
  saveCategory: (category: Category) => void;
  deleteCategory: (id: string) => void;
  updateOrderStatus: (id: string, status: OrderStatus) => void;
  assignCourier: (orderId: string, courierId: string) => void;
  adjustStock: (id: string, stock: number) => void;
  savePromotion: (promo: Promotion) => void;
  deletePromotion: (id: string) => void;
  saveStaff: (member: StaffMember) => void;
  toggleCustomerBlock: (id: string) => void;
  saveCourier: (courier: Courier) => void;
  saveSettings: (settings: StoreSettings) => void;
  updatePaymentStatus: (id: string, status: Payment['status']) => void;
}

const AdminContext = createContext<AdminContextValue | null>(null);

export const AdminProvider = ({ children }: { children: React.ReactNode }) => {
  const [products, setProducts] = useState<Product[]>(initialProducts);
  const [categories, setCategories] = useState<Category[]>(seedCategories);
  const [orders, setOrders] = useState<Order[]>(initialOrders);
  const [couriers, setCouriers] = useState<Courier[]>(initialCouriers);
  const [customers, setCustomers] = useState<Customer[]>(initialCustomers);
  const [promotions, setPromotions] = useState<Promotion[]>(initialPromotions);
  const [payments, setPayments] = useState<Payment[]>(initialPayments);
  const [staff, setStaff] = useState<StaffMember[]>(initialStaff);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [settings, setSettings] = useState<StoreSettings>({
    storeName: 'MaxSHOP',
    phone: '+998 71 200 00 00',
    email: 'info@maxshop.uz',
    address: 'Toshkent, Chilonzor tumani, Bunyodkor 12',
    currency: 'UZS',
    language: 'uz',
    freeDeliveryThreshold: 200000,
    deliveryFee: 12000,
    minOrderAmount: 50000,
    workingHours: '08:00 - 22:00',
    theme: 'light',
    orderNotifications: true,
    promoNotifications: false,
  });

  const notify = useCallback((message: string, type: Toast['type'] = 'success') => {
    const id = Date.now() + Math.random();
    setToasts((prev) => [...prev, { id, message, type }]);
    window.setTimeout(() => {
      setToasts((prev) => prev.filter((t) => t.id !== id));
    }, 3200);
  }, []);

  const dismissToast = useCallback((id: number) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  const saveProduct = useCallback(
    (product: Product) => {
      setProducts((prev) => {
        const exists = prev.some((p) => p.id === product.id);
        return exists ? prev.map((p) => (p.id === product.id ? product : p)) : [product, ...prev];
      });
    },
    [],
  );

  const deleteProduct = useCallback((id: string) => {
    setProducts((prev) => prev.filter((p) => p.id !== id));
  }, []);

  const saveCategory = useCallback((category: Category) => {
    setCategories((prev) => {
      const exists = prev.some((c) => c.id === category.id);
      return exists ? prev.map((c) => (c.id === category.id ? category : c)) : [...prev, category];
    });
  }, []);

  const deleteCategory = useCallback((id: string) => {
    setCategories((prev) => prev.filter((c) => c.id !== id));
  }, []);

  const updateOrderStatus = useCallback(
    (id: string, status: OrderStatus) => {
      setOrders((prev) => prev.map((o) => (o.id === id ? { ...o, status } : o)));
      setPayments((prev) =>
        prev.map((p) =>
          p.orderId === id
            ? { ...p, status: status === 'cancelled' ? 'refunded' : status === 'delivered' ? 'paid' : p.status }
            : p,
        ),
      );
    },
    [],
  );

  const assignCourier = useCallback((orderId: string, courierId: string) => {
    setOrders((prev) =>
      prev.map((o) => (o.id === orderId ? { ...o, courierId, status: o.status === 'new' ? 'confirmed' : o.status } : o)),
    );
    setCouriers((prev) =>
      prev.map((c) => {
        if (c.id === courierId) {
          return { ...c, activeOrders: c.activeOrders + 1, status: c.status === 'offline' ? 'online' : c.status };
        }
        return c;
      }),
    );
  }, []);

  const adjustStock = useCallback((id: string, stock: number) => {
    setProducts((prev) => prev.map((p) => (p.id === id ? { ...p, stock } : p)));
  }, []);

  const savePromotion = useCallback((promo: Promotion) => {
    setPromotions((prev) => {
      const exists = prev.some((p) => p.id === promo.id);
      return exists ? prev.map((p) => (p.id === promo.id ? promo : p)) : [promo, ...prev];
    });
  }, []);

  const deletePromotion = useCallback((id: string) => {
    setPromotions((prev) => prev.filter((p) => p.id !== id));
  }, []);

  const saveStaff = useCallback((member: StaffMember) => {
    setStaff((prev) => {
      const exists = prev.some((s) => s.id === member.id);
      return exists ? prev.map((s) => (s.id === member.id ? member : s)) : [member, ...prev];
    });
  }, []);

  const toggleCustomerBlock = useCallback((id: string) => {
    setCustomers((prev) => prev.map((c) => (c.id === id ? { ...c, blocked: !c.blocked } : c)));
  }, []);

  const saveCourier = useCallback((courier: Courier) => {
    setCouriers((prev) => {
      const exists = prev.some((c) => c.id === courier.id);
      return exists ? prev.map((c) => (c.id === courier.id ? courier : c)) : [courier, ...prev];
    });
  }, []);

  const saveSettings = useCallback((next: StoreSettings) => {
    setSettings(next);
  }, []);

  const updatePaymentStatus = useCallback((id: string, status: Payment['status']) => {
    setPayments((prev) => prev.map((p) => (p.id === id ? { ...p, status } : p)));
  }, []);

  const value = useMemo<AdminContextValue>(
    () => ({
      products,
      categories,
      orders,
      couriers,
      customers,
      promotions,
      payments,
      staff,
      settings,
      toasts,
      notify,
      dismissToast,
      saveProduct,
      deleteProduct,
      saveCategory,
      deleteCategory,
      updateOrderStatus,
      assignCourier,
      adjustStock,
      savePromotion,
      deletePromotion,
      saveStaff,
      toggleCustomerBlock,
      saveCourier,
      saveSettings,
      updatePaymentStatus,
    }),
    [
      products,
      categories,
      orders,
      couriers,
      customers,
      promotions,
      payments,
      staff,
      settings,
      toasts,
      notify,
      dismissToast,
      saveProduct,
      deleteProduct,
      saveCategory,
      deleteCategory,
      updateOrderStatus,
      assignCourier,
      adjustStock,
      savePromotion,
      deletePromotion,
      saveStaff,
      toggleCustomerBlock,
      saveCourier,
      saveSettings,
      updatePaymentStatus,
    ],
  );

  return <AdminContext.Provider value={value}>{children}</AdminContext.Provider>;
};

export const useAdmin = () => {
  const ctx = useContext(AdminContext);
  if (!ctx) throw new Error('useAdmin must be used within AdminProvider');
  return ctx;
};
